"""Render staff-edited correspondence and identify files generated by this workspace."""
from io import BytesIO

from pypdf import PdfReader
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.platypus import SimpleDocTemplate, Spacer

from app.workspace_documents import _paragraph

CREATOR = "ZeroUpfront discharge correspondence"


def is_generated(raw):
    return (PdfReader(BytesIO(raw)).metadata or {}).get("/Creator") == CREATOR


def render(case, decision, text):
    if not all(case.get(key) for key in ("facility", "insurer", "id", "revision", "encounter", "member")):
        raise ValueError("The saved claim lacks correspondence identifiers. Verify the recipient and record an externally prepared PDF.")
    if not text.strip() or any(not ch.isprintable() and ch not in "\r\n\t" for ch in text):
        raise ValueError("Enter printable correspondence text.")
    if "[list only the relevant documents and page numbers]" in text:
        raise ValueError("Replace the evidence placeholder with the actual response before downloading.")
    stream = BytesIO()
    styles = getSampleStyleSheet()
    subject = "Response to payer query" if decision["data"]["outcome"] == "query" else "Appeal of payer decision"
    fields = (("Hospital", case["facility"]), ("Recipient", case["insurer"]), ("Claim", case["id"]),
              ("Evidence revision", case["revision"]), ("Encounter", case["encounter"]),
              ("Member", case["member"]), ("Written payer reference", decision["data"]["reference"]),
              ("Payer decision record", decision["id"]))
    body = [_paragraph(subject, styles["Heading1"])]
    body.extend(_paragraph(f"{label}: {value}", styles["BodyText"]) for label, value in fields)
    body.append(Spacer(1, 16))
    body.extend(_paragraph(line.strip(), styles["BodyText"]) for line in text.splitlines() if line.strip())
    def identify(canvas, _doc):
        canvas.setCreator(CREATOR)
        canvas.setTitle(subject)
    SimpleDocTemplate(stream, pagesize=A4, invariant=True).build(body, onFirstPage=identify, onLaterPages=identify)
    return stream.getvalue()
